ST.xhtml:p:
(*心跳包，写入0x3A，保证使能*)
g_noHeart_Beat := 58;

R_Trigger(CLK := g_bF050Home );
(*R_Trigger1(CLK := g_bFBM11XEnable OR g_bMnualAnalogEnable);*)

(*回零,F轴到0刻度*)
IF R_Trigger.Q THEN
  g_bF050Home := false; 
  g_noPositionSetFocus := 0;    
END_IF;

IF g_bFBS12KEnable THEN
  dFPosFb := g_dAnalogPosition;
  g_bFBS12KEnable := FALSE;
  g_bFocusEnable := FALSE;
  nState := 5;
ELSIF g_bMnualAnalogEnable THEN
  dFPosFb := g_dMnualAnalogPosition;
  g_bMnualAnalogEnable := FALSE;
  nState := 5;
END_IF;

CASE nState OF
  0:
    nState := 0;
  5:  (*步进电机调焦*)
    g_noPositionSetFocus := LREAL_TO_DINT(1000.0*dFPosFb);
    nState := 10;      
  10:(*调焦完成*)
    IF g_niBS12KActualFocus>g_noPositionSetFocus-50 AND g_niBS12KActualFocus< g_noPositionSetFocus+50 THEN
      g_bFocusDone := TRUE;
      nState := 0;
    END_IF;
END_CASE;    

(*坐标反馈*)
g_dFaxisAnoagePosFb := DINT_TO_LREAL(g_niBS12KActualFocus)/1000.0;   
(*调焦头使能警，0异常，1正常*)
IF g_niBS12KStatusEnable = 1   THEN
  g_Alarm.alarmArray[357] := 0;  
ELSE
  IF  g_bCloseEnableAlarm_BS12K THEN
     g_Alarm.alarmArray[357] := 0; 
  ELSE
    g_Alarm.alarmArray[357] := 1085;  
  END_IF;  
END_IF;  
(*上保护镜温度报警*)
IF g_niBS12KTopProtectiveWindowTemperAlarm = 1 THEN
  g_Alarm.alarmArray[358] := 0;  
ELSE
  IF  g_bCloseUpProtectWindowAlarm_BS12K  THEN
    g_Alarm.alarmArray[358] := 0; 
  ELSE
    g_Alarm.alarmArray[358] := 1086;  
  END_IF; 
END_IF; 
(*腔体温度报警*)
IF g_niBS12KCavityTemperatureAlarm = 1 THEN
  g_Alarm.alarmArray[359] := 0;  
ELSE
  IF  g_bClosedCavityTemperatureAlarm_BS12K THEN
    g_Alarm.alarmArray[359] := 0; 
  ELSE
    g_Alarm.alarmArray[359] := 1087; 
  END_IF; 
END_IF;
(*聚焦镜温度报警*)
IF g_niBS12KFocusLensTemperatuerAlarm = 1 THEN
  g_Alarm.alarmArray[363] := 0;  
ELSE
  IF  g_bCloseFocusLensAlarm_BS12K THEN
    g_Alarm.alarmArray[363] := 0; 
  ELSE
    g_Alarm.alarmArray[363] := 1091;
  END_IF;   
END_IF; 
(*下保护镜温度报警*)  
IF g_niBS12KBottomProtectiveWindowTemperAlarm = 1 THEN
  g_Alarm.alarmArray[360] := 0;  
ELSE
  IF  g_bCloseDownProtectWindowAlarm_BS12K THEN
    g_Alarm.alarmArray[360] := 0; 
  ELSE
    g_Alarm.alarmArray[360] := 1088; 
  END_IF; 
END_IF; 
(*腔体压力报警*)
IF g_niBS12KCavityAlarmPressure = 1 THEN
  g_Alarm.alarmArray[364] := 0;  
ELSE
  IF  g_bCloseCavityPressureAlarm_BS12K THEN
    g_Alarm.alarmArray[364] := 0; 
  ELSE
    g_Alarm.alarmArray[364] := 1092;
  END_IF;  
END_IF;
(*下保护镜到位报警信号*)  
IF g_niBS12KBottomProtectiveWindowInPosition = 1 THEN
  g_Alarm.alarmArray[365] := 0;  
ELSE
  IF  g_bCloseDownProtectWindowInPosAlarm_BS12K THEN
    g_Alarm.alarmArray[365] := 0; 
  ELSE
    g_Alarm.alarmArray[365] := 1093; 
  END_IF; 
END_IF; 
(*电机故障代码*)  
IF g_niBS12KFocusMotorErrorCode <>0 THEN
  g_Alarm.alarmArray[361] := 1089;  
ELSE
  IF  FALSE THEN
    g_Alarm.alarmArray[361] := 0; 
  ELSE
    g_Alarm.alarmArray[361] := 0; 
  END_IF;  
END_IF; 
(*调焦头WIFI报警*)  
IF g_niBS12KStatusWIF = 1  AND NOT g_bCloseEnableAlarm_BS12K THEN
  g_Alarm.alarmArray[362] := 0;  
ELSE
  IF  g_bCloseWIFIAlarm_BS12K THEN
    g_Alarm.alarmArray[362] := 0; 
  ELSE
    g_Alarm.alarmArray[362] := 1090;  
  END_IF; 
END_IF;
